        _DESCRIPTION = DESCRIPTION,
        _TAGS = TAGS,
        _MEMBERSHIP_MODE = membershipMode ?? MEMBERSHIP_MODE,
        _MEMBERS = MEMBERS,
        _QUERY = QUERY,
        _CREATED_AT = createdAt ?? CREATED_AT,
        _UPDATED_AT = updatedAt ?? UPDATED_AT,
        _PROVENANCE = PROVENANCE,
        _DATASET_CID = datasetCid ?? DATASET_CID;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? GROUP_IDOffset = _GROUP_ID == null ? null
        : fbBuilder.writeString(_GROUP_ID!);
    final int? NAMEOffset = _NAME == null ? null
        : fbBuilder.writeString(_NAME!);
    final int? DESCRIPTIONOffset = _DESCRIPTION == null ? null
        : fbBuilder.writeString(_DESCRIPTION!);
    final int? TAGSOffset = _TAGS == null ? null
        : fbBuilder.writeList(_TAGS!.map(fbBuilder.writeString).toList());
    final int? MEMBERSOffset = _MEMBERS == null ? null
        : fbBuilder.writeList(_MEMBERS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? QUERYOffset = _QUERY?.getOrCreateOffset(fbBuilder);
    final int? CREATED_ATOffset = _CREATED_AT == null ? null
        : fbBuilder.writeString(_CREATED_AT!);
    final int? UPDATED_ATOffset = _UPDATED_AT == null ? null
        : fbBuilder.writeString(_UPDATED_AT!);
    final int? PROVENANCEOffset = _PROVENANCE == null ? null
        : fbBuilder.writeList(_PROVENANCE!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? DATASET_CIDOffset = _DATASET_CID == null ? null
        : fbBuilder.writeString(_DATASET_CID!);
    fbBuilder.startTable(11);
    fbBuilder.addOffset(0, GROUP_IDOffset);
    fbBuilder.addOffset(1, NAMEOffset);
    fbBuilder.addOffset(2, DESCRIPTIONOffset);
    fbBuilder.addOffset(3, TAGSOffset);
    fbBuilder.addInt8(4, _MEMBERSHIP_MODE?.value);
    fbBuilder.addOffset(5, MEMBERSOffset);
    fbBuilder.addOffset(6, QUERYOffset);
    fbBuilder.addOffset(7, CREATED_ATOffset);
    fbBuilder.addOffset(8, UPDATED_ATOffset);
    fbBuilder.addOffset(9, PROVENANCEOffset);
    fbBuilder.addOffset(10, DATASET_CIDOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
